raw_commands:
{#- URY POS receipt for thermal printers (ESC/POS, 80 mm, 48 columns).
    Sent to QZ Tray as raw commands. For 58 mm paper set W to 32. -#}
{%- set W = 48 -%}
{%- set ESC = "\x1B" -%}
{%- set GS = "\x1D" -%}
{%- set LF = "\n" -%}
{%- set INIT = ESC ~ "@" -%}
{%- set LEFT = ESC ~ "a" ~ "\x00" -%}
{%- set CENTER = ESC ~ "a" ~ "\x01" -%}
{%- set BOLD_ON = ESC ~ "E" ~ "\x01" -%}
{%- set BOLD_OFF = ESC ~ "E" ~ "\x00" -%}
{%- set BIG_ON = GS ~ "!" ~ "\x11" -%}
{%- set BIG_OFF = GS ~ "!" ~ "\x00" -%}
{%- set CUT = GS ~ "V" ~ "\x41" ~ "\x03" -%}
{%- set RULE = "-" * W -%}
{%- macro row(left, right, w=48) -%}
{%- set r = right | string -%}
{%- set l = (left | string)[: w - (r | length) - 1] -%}
{{ l }}{{ " " * (w - (l | length) - (r | length)) }}{{ r }}{{ "\n" }}
{%- endmacro -%}
{%- macro money(value) -%}{{ frappe.utils.fmt_money(value or 0, precision=2) }}{%- endmacro -%}
{%- set company = frappe.get_cached_doc("Company", doc.company) -%}
{{- INIT -}}
{{- CENTER -}}{{- BOLD_ON -}}{{- BIG_ON -}}{{ (doc.restaurant or company.company_name)[:W // 2] }}{{ LF }}{{- BIG_OFF -}}{{- BOLD_OFF -}}
{%- if doc.restaurant and doc.restaurant != company.company_name -%}{{ company.company_name[:W] }}{{ LF }}{%- endif -%}
{%- if company.phone_no -%}{{ _("Tel") }}: {{ company.phone_no }}{{ LF }}{%- endif -%}
{%- if company.tax_id -%}{{ _("Tax ID") }}: {{ company.tax_id }}{{ LF }}{%- endif -%}
{{- LEFT -}}{{ RULE }}{{ LF }}
{%- if doc.custom_ury_order_number -%}{{- CENTER -}}{{- BOLD_ON -}}{{- BIG_ON -}}{{ _("Order") }} #{{ doc.custom_ury_order_number }}{{ LF }}{{- BIG_OFF -}}{{- BOLD_OFF -}}{{- LEFT -}}{%- endif -%}
{{ row(_("Invoice") ~ ": " ~ doc.name, doc.get_formatted("posting_date"), W) }}
{{- row(_("Time") ~ ": " ~ (doc.posting_time | string)[:5], doc.order_type or "", W) -}}
{%- if doc.restaurant_table -%}{{ row(_("Table") ~ ": " ~ doc.restaurant_table, (_("Pax") ~ ": " ~ doc.no_of_pax) if doc.no_of_pax else "", W) }}{%- endif -%}
{%- if doc.waiter -%}{{ row(_("Waiter") ~ ": " ~ (frappe.db.get_value("User", doc.waiter, "first_name") or doc.waiter), "", W) }}{%- endif -%}
{%- if doc.customer_name -%}{{ row(_("Customer") ~ ": " ~ doc.customer_name, doc.mobile_number or "", W) }}{%- endif -%}
{{ RULE }}{{ LF }}
{{- BOLD_ON -}}{{ row(_("Item"), _("Amount"), W) }}{{- BOLD_OFF -}}
{{ RULE }}{{ LF }}
{%- for item in doc.items -%}
{{ item.item_name[:W] }}{{ LF }}
{{- row("  " ~ (item.qty | float | round(3) | string).rstrip("0").rstrip(".") ~ " x " ~ money(item.rate), money(item.amount), W) -}}
{%- endfor -%}
{{ RULE }}{{ LF }}
{{- row(_("Subtotal"), money(doc.net_total), W) -}}
{%- for tax in doc.taxes -%}{%- if tax.tax_amount -%}{{ row(tax.description, money(tax.tax_amount), W) }}{%- endif -%}{%- endfor -%}
{%- if doc.discount_amount -%}{{ row(_("Discount"), "-" ~ money(doc.discount_amount), W) }}{%- endif -%}
{%- if doc.rounding_adjustment -%}{{ row(_("Rounding"), money(doc.rounding_adjustment), W) }}{%- endif -%}
{#- Currency code, not symbol: ESC/POS code pages can't print most symbols. -#}
{{- BOLD_ON -}}{{ row(_("TOTAL"), doc.currency ~ " " ~ money(doc.rounded_total or doc.grand_total), W) }}{{- BOLD_OFF -}}
{%- if doc.payments | selectattr("amount") | list -%}
{{ RULE }}{{ LF }}
{%- for p in doc.payments -%}{%- if p.amount -%}{{ row(p.mode_of_payment, money(p.amount), W) }}{%- endif -%}{%- endfor -%}
{%- if doc.change_amount -%}{{ row(_("Change"), money(doc.change_amount), W) }}{%- endif -%}
{%- endif -%}
{{ RULE }}{{ LF }}
{{- CENTER -}}{{ _("Thank you! Please visit again") }}{{ LF }}{{ LF }}{{ LF }}
{{- CUT -}}
